window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q05"]=window.__LIBQ["the-gioi-hoan-my"]["q05"]||{};window.__LIBQ["the-gioi-hoan-my"]["q05"]["map"]={"updatedAt":"2026-07-21","count":110,"nodes":[{"id":"lam-vien-hoang-gia-hoa-quoc","name":"Lâm viên hoàng gia Hỏa quốc","cn":"","capDo":"khac","parentId":"hoang-do-hoa-quoc","blurb":"Khu lâm viên hoàng gia rộng lớn tại Hoàng Đô Hỏa quốc, nơi quần hùng vực ngoại tụ hội.","detail":"Lâm viên có cầu, cung điện và lầu các, được Hỏa Linh Nhi dùng làm nơi tiếp đón cường giả các vực. Người của Bất Lão sơn cùng nhân vật thuộc nhiều đại giáo cũng tới đây giữa tin đồn Thạch Hạo tái xuất.","theLucLienQuan":["Hỏa quốc","Bất Lão sơn","Tây Thiên giáo","Tiệt Thiên giáo"],"nguon":["@c0401"]},{"id":"biet-vien-hoang-gia-hoa-quoc","name":"Biệt viện hoàng gia Hỏa quốc","cn":"","capDo":"khac","parentId":"hoang-do-hoa-quoc","blurb":"Biệt viện hoàng gia nơi Hỏa Linh Nhi mở tiệc sau khi xuất quan.","detail":"Hỏa Linh Nhi mời cường giả các tộc từ vực ngoại tới biệt viện dự tiệc, vừa tiếp đón những người từng tìm mình vừa dò xét tin Thạch Hạo có thể đã xuất hiện.","theLucLienQuan":["Hỏa quốc"],"nguon":["@c0401"]},{"id":"biet-vien-tu-hoi","name":"Biệt viện tụ hội","cn":"","capDo":"khac","parentId":"hoang-do-hoa-quoc","blurb":"Biệt viện tại Hoàng Đô Hỏa quốc, nơi tu sĩ Hoang Vực và cường giả vực ngoại tập trung giao lưu.","detail":"Quần thể sân vườn rộng lớn có tiểu truyền tống trận tại cổng để sàng lọc tu vi. Bên trong có nhiều đình đài, cổ mộc, linh chu và linh dược lâu năm; các tu sĩ thuộc nhiều tộc phân tán tại các khu vực để gặp gỡ, trao đổi bảo vật và bảo thuật.","theLucLienQuan":["Hỏa quốc"],"nguon":["@c0402"]},{"id":"vo-dai-noi-tren-khong","name":"Võ đài nổi trên không","cn":"","capDo":"khac","parentId":"biet-vien-tu-hoi","blurb":"Bình đài quyết đấu được đại trận nâng lên giữa không trung trong buổi tụ hội.","detail":"Võ đài được dựng trên trời để Cửu đầu sư tử quyết đấu với thiên tài số một Hắc Vân tộc, tránh làm hư hại dược thảo quý trong trang viên.","theLucLienQuan":["Hỏa tộc","Hắc Vân tộc"],"nguon":["@c0403"]},{"id":"trang-vien","name":"Trang viên","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi tu sĩ Hoang Vực và sinh linh vực ngoại tụ tập, chứng kiến cuộc đối đầu giữa Thạch Hạo với các cường giả.","detail":"Tại trang viên, Thạch Hạo dùng tràng vực thân thể áp chế người của Bất Lão sơn, phá sát trận Tứ Tượng rồi chém chết Viêm Mãng Vương trước mặt quần hùng. Sau đó, nhiều tu sĩ Bất Lão sơn tiếp tục kéo tới đây.","theLucLienQuan":["Bất Lão sơn","Viêm Mãng tộc"],"nguon":["@c0406"]},{"id":"thanh-son-cua-bat-lao-son","name":"Thánh sơn của Bất Lão sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi các thành viên Bất Lão sơn tập trung và là địa điểm Tần Thủ Thành muốn áp giải Thạch Hạo về chịu xử lý.","detail":"Bất Lão sơn có số thành viên ít nhưng đều tập trung tại ngọn thánh sơn này. Sau khi Tần Siêu bị phế tu vi, Tần Thủ Thành yêu cầu Thạch Hạo chịu trói và theo mình trở về đây.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0407"]},{"id":"to-dia-thach-toc","name":"Tổ địa Thạch tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi lưu giữ truyền thừa của Thạch tộc, được đánh giá còn kinh người hơn truyền thừa tại tổ địa Hỏa quốc.","detail":"Lão Vương Hỏa quốc cho rằng nếu may mắn đạt được truyền thừa tại đây, Thạch Hạo có thể nhanh chóng đột phá khỏi Liệt Trận Vương cảnh.","theLucLienQuan":["Thạch tộc"],"nguon":["@c0410"]},{"id":"hoa-quat","name":"Hỏa quật","cn":"","capDo":"khac","parentId":null,"blurb":"Tuyệt địa quanh năm chìm trong lửa, là nơi sinh sống của bộ tộc Hỏa Nha.","detail":"Nhiệt độ trong động cực cao. Nguyệt Thiền tiên tử từng đến đây ngắt hoa Ly Hỏa Linh để chuẩn bị cho việc luyện chế niết bàn.","theLucLienQuan":[],"nguon":["@c0410"]},{"id":"to-dia-hoa-quoc","name":"Tổ địa Hỏa quốc","cn":"","capDo":"khac","parentId":"hoa-quoc","blurb":"Thánh thổ của Hỏa quốc, từng giúp Thạch Hạo nhanh chóng tăng cấp.","detail":"Truyền thừa tại đây được lão Vương Hỏa quốc dùng làm mốc so sánh khi tiết lộ rằng truyền thừa tại tổ địa Thạch tộc còn kinh người hơn.","theLucLienQuan":["Hỏa quốc"],"nguon":["@c0410"]},{"id":"hoang-cung-thach-quoc","name":"Hoàng cung Thạch quốc","cn":"","capDo":"khac","parentId":"thach-quoc","blurb":"Nơi Nhân Hoàng nắm giữ những phương thuốc còn lại của Thạch quốc, đồng thời gắn với quyền kế thừa đại thống.","detail":"Hoàng cung là nơi lưu giữ phần truyền thừa phương thuốc hiện còn của hoàng tộc Thạch quốc, nhưng bộ phương thuốc này đã thiếu mất một phương phối hợp quan trọng. Thạch Hạo được nhận định có khả năng kế thừa đại thống nếu tới đây, song hiện chưa muốn tranh đoạt ngôi vị.","theLucLienQuan":["Thạch quốc"],"nguon":["@c0411"]},{"id":"hoa-diem-son","name":"Hỏa Diễm sơn","cn":"","capDo":"khac","parentId":"hoang-vuc","blurb":"Dãy núi nằm ở cực Tây Hoang Vực, có kỳ dược dùng làm chủ dược cho phương thuốc trợ giúp người tu hành trở thành Tôn giả.","detail":"Hỏa Diễm sơn là một tuyệt địa nguy hiểm, người tiến vào phải đối mặt với cảnh cửu tử nhất sinh. Kỳ dược sinh trưởng tại đây là trân bảo hi thế và có thể làm chủ dược cho một phương thuốc trợ giúp đột phá tới Tôn giả.","theLucLienQuan":[],"nguon":["@c0412"]},{"id":"vung-dat-mau-vang","name":"Vùng đất màu vàng","cn":"","capDo":"khac","parentId":"hoang-vuc","blurb":"Cấm địa tại Hoang Vực có đất đá màu vàng và ẩn chứa thần tính bất hủ có thể dùng để luyện thể.","detail":"Khu vực này được bao phủ bởi quy tắc màu vàng cực kỳ nguy hiểm, có thể chém nát người xâm nhập. Thần tính bất hủ trong đất đá mang lại giá trị luyện thể lớn nhưng rất khó tiếp cận.","theLucLienQuan":[],"nguon":["@c0412"]},{"id":"thu-son-tay-lang","name":"Thú sơn Tây Lăng","cn":"","capDo":"khac","parentId":"tay-lang","blurb":"Khu cổ lăng chôn thi hài hung thú thái cổ, đồng thời là nơi từng xuất hiện Trúc Hoàng Tuyền.","detail":"Thú sơn Tây Lăng có những vùng âm khí gây tai họa xen lẫn nơi linh khí dồi dào. Các di chủng bảo vệ cổ mộ lâu năm đã hình thành một thế lực mạnh tại đây; Thạch Hạo dự tính tới khu vực này để tìm Trúc Hoàng Tuyền, trong khi những cổ mộ còn có khả năng lưu giữ nguyên thủy bảo cốt.","theLucLienQuan":["Thú sơn Tây Lăng"],"nguon":["@c0412"]},{"id":"duoc-do","name":"Dược Đô","cn":"","capDo":"thanh","parentId":"hoa-quoc","blurb":"Cổ thành thuộc Hỏa quốc, nổi tiếng từ thời Thượng Cổ nhờ dược thảo và nghề luyện dược.","detail":"Dược Đô tập trung nhiều Dược Sư, linh dược và dược thực Thông Linh. Tường thành thấp và đổ nát nhưng bên trong phồn thịnh; vùng đất được truyền là thấm tinh khí cùng dược tính của Dược Thần nên đặc biệt thích hợp cho cây cỏ sinh trưởng.","theLucLienQuan":[],"nguon":["@c0415"]},{"id":"vuon-thuoc-ngoai-duoc-do","name":"Vườn thuốc ngoài Dược Đô","cn":"","capDo":"khac","parentId":"duoc-do","blurb":"Khu vực vườn thuốc bao quanh Dược Đô, nơi trồng và nuôi dưỡng nhiều loại dược thảo.","detail":"Các vườn thuốc được bố trí trận pháp tụ tinh khí mười phương rồi dẫn vào lòng đất để nuôi dược thảo. Hoàng Kim Dược Điệp không thuần huyết cũng xuất hiện tại đây, khiến cây cỏ thêm sinh cơ và hoa nở.","theLucLienQuan":[],"nguon":["@c0415"]},{"id":"day-nui-gan-duoc-do","name":"Dãy núi gần Dược Đô","cn":"","capDo":"vuc","parentId":"hoa-quoc","blurb":"Dãy núi gần Dược Đô, nơi đoàn Thạch Hạo xuất hiện sau hành trình xuyên hư không.","detail":"Do Hư Không thú bì không thể định vị hoàn toàn chính xác trên quãng đường quá xa, đoàn người tới dãy núi này thay vì vào thẳng Dược Đô. Nơi đây có linh khí dồi dào, mùi thuốc lan tỏa và nhiều vườn thuốc ẩn hiện; từ đó họ bay hơn trăm dặm mới thấy cổ thành.","theLucLienQuan":[],"nguon":["@c0415"]},{"id":"than-coc","name":"Thần cốc","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc có cổ dược thần thánh được trận pháp bảo vệ và rải rác những mảnh xương nghi là Chân Hoàng cốt.","detail":"Thần cốc có khả năng là nơi Chân Hoàng vẫn lạc. Tin phát hiện thần vật bất hủ tại đây được truyền tới các đại nhân vật trong Dược đô, báo hiệu nơi này sắp trở thành tâm điểm tranh đoạt.","theLucLienQuan":[],"nguon":["@c0416"]},{"id":"dao-dai-quan-sat-than-coc","name":"Đạo đài quan sát Thần cốc","cn":"","capDo":"khac","parentId":"than-coc","blurb":"Tảng đá lớn cho phép người đứng trên đó nhìn mơ hồ xuyên qua trung tâm cổ trận Thần cốc.","detail":"Đây là vị trí quan sát đặc biệt mà từ đó các đại nhân vật có thể nhìn vào trung tâm Thần cốc và kiểm tra di cốt chim thần cấp Thiên. Những nơi khác không thể nhìn thấu trung tâm trận pháp do cấm chế và hư không vặn vẹo che khuất.","theLucLienQuan":["Thần Dược môn"],"nguon":["@c0417"]},{"id":"nui-niet-ban-cua-duoc-than","name":"Núi niết bàn của Dược thần","cn":"","capDo":"khac","parentId":"duoc-do","blurb":"Ngọn núi nhỏ nằm tại trung tâm Dược Đô, được xem là vùng đất thần thánh nhất của thành.","detail":"Tương truyền Dược thần thượng cổ từng niết bàn tại đây. Dưới lòng núi được đồn có tiên khí và ánh lửa, đồng thời tồn tại giếng tổ của Thần Dược môn.","theLucLienQuan":["Thần Dược môn"],"nguon":["@c0420"]},{"id":"gieng-to-cua-than-duoc-mon","name":"Giếng tổ của Thần Dược môn","cn":"","capDo":"khac","parentId":"nui-niet-ban-cua-duoc-than","blurb":"Giếng cổ nằm trên núi niết bàn của Dược thần, sâu thẳng xuống lòng đất và liên tục tỏa mây mù.","detail":"Bên trong giếng có một chiếc đỉnh cổ chìm nổi như đang được nung nấu. Cô gái áo xám được Thần Dược môn cho mượn nơi này theo giao ước đổi lấy một lần giúp đỡ môn phái.","theLucLienQuan":["Thần Dược môn"],"nguon":["@c0420"]},{"id":"ngon-nui-thap-cua-than-duoc-mon","name":"Ngọn núi thấp của Thần Dược môn","cn":"","capDo":"khac","parentId":"duoc-do","blurb":"Ngọn núi thấp ở trung tâm Dược đô, nơi Thần Dược môn được khai sáng và Giếng tổ tọa lạc.","detail":"Cô gái áo xám cư trú trên núi và cho phép Thạch Hạo đi lên gặp mình, trong khi những người đồng hành của nó bị chặn dưới chân núi. Khu vực Giếng tổ trên núi được vô số trận pháp do Thần Linh bố trí bảo vệ.","theLucLienQuan":["Thần Dược môn"],"nguon":["@c0421"]},{"id":"dai-dien-dong-thau-cua-bat-lao-son","name":"Đại điện đồng thau của Bất Lão sơn","cn":"","capDo":"khac","parentId":"bat-lao-son","blurb":"Trung tâm quyền lực của Bất Lão sơn, nơi các nhân vật cấp cao bí mật nghị sự.","detail":"Đại điện nằm giữa vùng núi Bất Lão sơn tại Huyền Vực. Tại đây, những người cấp cao bàn bạc việc đón về đứa trẻ mang một nửa huyết thống của Bất Lão sơn và phát ra pháp chỉ được đóng thần ấn.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0422"]},{"id":"vuon-thuoc-cua-lam-con","name":"Vườn thuốc của Lâm Côn","cn":null,"capDo":"khac","parentId":"duoc-do","blurb":"Khu vườn nhỏ dưới chân núi trong địa bàn Thần Dược môn, nơi Lâm Côn trồng các kỳ dược quý hiếm.","detail":"Vườn thuốc có linh khí nồng đậm và được trận pháp bảo vệ, bên ngoài phủ sương mù. Bên trong trồng Hoàng Kim thảo, Lạc Nguyệt hoa, Tử Tinh lan và Lưu kim tuế nguyệt.","theLucLienQuan":["Thần Dược môn"],"nguon":["@c0423"]},{"id":"hang-co-duoi-long-dat","name":"Hang cổ dưới lòng đất","cn":"","capDo":"khac","parentId":"than-coc","blurb":"Đường hầm sâu hơn trăm trượng nối bên ngoài với ba tầng trận pháp đầu tiên của Thần cốc.","detail":"Đường hầm do cổ nhân liên tiếp phá trận tạo thành trước khi bỏ mạng. Bên trong vẫn còn tàn dư phù văn nguy hiểm.","theLucLienQuan":["Các cường giả Dược đô"],"nguon":["@c0424"]},{"id":"tang-tran-phap-thu-nhat-than-coc","name":"Tầng trận pháp thứ nhất","cn":"","capDo":"khac","parentId":"than-coc","blurb":"Không gian đầu tiên bên trong hệ thống thần trận của Thần cốc, rộng lớn như một thế giới độc lập.","detail":"Khu vực rộng đến mức khó nhìn thấy điểm cuối nhưng thực vật thưa thớt vì tinh khí bị trận pháp tụ linh hút về trung tâm.","theLucLienQuan":[],"nguon":["@c0424"]},{"id":"tang-tran-phap-thu-hai-than-coc","name":"Tầng trận pháp thứ hai","cn":"","capDo":"khac","parentId":"than-coc","blurb":"Tầng không gian có diện tích gần tương đương tầng trận pháp thứ nhất.","detail":"Nơi này gần như không có ngọn cỏ hay vật có giá trị. Lối chuyển tiếp mang dấu hiệu của phù văn không gian.","theLucLienQuan":[],"nguon":["@c0424"]},{"id":"tang-tran-phap-thu-ba-than-coc","name":"Tầng trận pháp thứ ba","cn":"","capDo":"khac","parentId":"than-coc","blurb":"Khu vực cấm chế chưa bị phá hoàn toàn, nơi con của Dược thần đã bỏ mạng.","detail":"Tầng trận pháp chứa di hài con của Dược thần, nhiều mảnh pháp khí và nửa miếng đồng thau liên quan đến đầu mối tìm Hoàng điệp. Trận văn và sát cơ tại đây vẫn chưa bị loại bỏ hoàn toàn.","theLucLienQuan":["Thần Dược môn"],"nguon":["@c0424"]},{"id":"tieu-the-gioi-trong-hop-bau","name":"Tiểu thế giới trong hộp báu","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian hư vô nằm bên trong Thế giới hộp báu, được mở ra khi các ký hiệu trên hộp đồng thau kết thành một cánh cửa.","detail":"Tiểu thế giới này tối tăm, diện tích không lớn và ở giữa chỉ có một bàn đá đặt tấm da thú do Dược thần lưu lại.","theLucLienQuan":[],"nguon":["@c0426"]},{"id":"dia-mach-to-can-duoc-do","name":"Địa mạch tổ căn Dược đô","cn":"","capDo":"khac","parentId":"duoc-do","blurb":"Địa mạch tổ căn dưới Dược đô, nơi Dược thần từng đưa trứng Hoàng điệp tới hấp thu tinh hoa thiên địa.","detail":"Nơi này còn được gọi là cửa Sinh trong thiên địa, có ao linh dịch mang khí tức bất hủ. Bình Thần Băng được đặt dưới đáy ao và được trận pháp truyền tống ra ngoài sau khi cơ chế thu hồi được kích hoạt.","theLucLienQuan":["Dược Thần môn"],"nguon":["@c0426"]},{"id":"khu-vuon-hoang-cua-duoc-than","name":"Khu vườn hoang của Dược Thần","cn":"","capDo":"khac","parentId":"duoc-do","blurb":"Phế tích tương truyền từng là nơi Dược Thần dựng nhà để ở.","detail":"Khu vườn nằm cách xa núi thấp trung tâm Dược đô. Bên dưới lớp gạch vụn có một tế đàn nhỏ dùng để tiếp nhận bình Thần Băng.","theLucLienQuan":[],"nguon":["@c0427"]},{"id":"hoang-do-hoa-quoc","name":"Hoàng đô Hỏa quốc","cn":"","capDo":"thanh","parentId":"hoa-quoc","blurb":"Kinh đô Hỏa quốc, nơi pháp chỉ của Bất Lão sơn xuyên qua vực bích và giáng xuống.","detail":"Người trung niên giữ pháp chỉ lưu tại đây để truyền lệnh triệu kiến Thạch Hạo. Sau nhiều lần thúc ép không thành, người này bị Thạch Hạo công khai yêu cầu phải tự tới Dược đô yết kiến.","theLucLienQuan":["Hỏa quốc","Bất Lão sơn"],"nguon":["@c0429","@c0446"]},{"id":"thien-than-son","name":"Thiên Thần sơn","cn":"","capDo":"khac","parentId":"hoang-vuc","blurb":"Một Thái Cổ Thần Sơn gắn với Vân Hi, có nhiều linh dược.","detail":"Thạch Hạo từng muốn tìm một Thái Cổ Thần Sơn thích hợp để nuôi Hoàng điệp và nhắc tới việc đến Thiên Thần sơn. Vân Hi không đồng ý vì lo thần trùng sẽ ăn sạch linh dược tại đó.","theLucLienQuan":["Thiên Thần sơn"],"nguon":["@c0429"]},{"id":"hoang-do-thach-quoc","name":"Hoàng đô Thạch quốc","cn":"","capDo":"thanh","parentId":"thach-quoc","blurb":"Kinh đô Thạch quốc và là điểm đến tiếp theo của Thạch Hạo sau khi nhận tin về thư từ vực ngoại.","detail":"Một bức thư từ vực ngoại được đưa tới Võ Vương phủ rồi chuyển sang Hoang Thiên hầu phủ. Vì cha mẹ và ông nội đều đang ở vực ngoại, Thạch Hạo quyết định trở về hoàng đô để xem xét bức thư, dù có khả năng người của Bất Lão sơn đang chờ tại đó.","theLucLienQuan":["Thạch quốc","Võ Vương phủ","Hoang Thiên hầu phủ","Bất Lão sơn"],"nguon":["@c0429","@c0446"]},{"id":"dai-vuc-lao-tu","name":"Đại vực lao tù","cn":"","capDo":"vuc","parentId":null,"blurb":"Cách gọi được ghi trên Thái Cổ trận pháp đối với đại vực nơi Vân Hi và mọi người đang sinh sống.","detail":"Thái Cổ trận pháp có thể mở bằng đôi bao cổ tay của Thiên Nhân Tộc để rời khỏi đại vực lao tù, nhưng ghi chép không nêu rõ điểm đến.","theLucLienQuan":["Thiên Nhân Tộc","Thiên Thần Sơn"],"nguon":["@c0430"]},{"id":"hoang-vuc","name":"Hoang vực","cn":"","capDo":"vuc","parentId":null,"blurb":"Đại vực mà Thiên Nhân Tộc đang vội tìm cách rời đi.","detail":"Vân Hi cho biết nguyên nhân Thiên Nhân Tộc muốn rời Hoang vực liên quan đến một sự thật quá mức đáng sợ, nhưng chưa tiết lộ nội dung cụ thể.","theLucLienQuan":["Thiên Nhân Tộc","Thiên Thần Sơn"],"nguon":["@c0430"]},{"id":"khu-pho-duoc-lieu-duoc-do","name":"Khu phố dược liệu Dược đô","cn":"","capDo":"khac","parentId":"duoc-do","blurb":"Khu phố náo nhiệt chuyên giao dịch dược liệu, xương cốt và khoáng thạch tại Dược đô.","detail":"Nhóm Thạch Hạo gặp nhiều sạp bán cốt dược và khoáng thạch tại đây. Thạch Hạo nhìn thấu các món hàng chắp vá, đồng thời mua được khối cốt đen chứa thần quang từ một đống xương và khoáng thạch tơi tả.","theLucLienQuan":[],"nguon":["@c0416"]},{"id":"son-coc-co-hoang-cot","name":"Sơn cốc có Hoàng cốt","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc được báo là nơi phát hiện nhiều mảnh xương có khả năng thuộc về Chân Hoàng.","detail":"Một số mảnh xương được cho là còn lưu giữ phù văn nguyên thủy và sức mạnh bất hủ. Nơi này cũng được nhắc tới cùng cổ dược thần thánh sắp xuất thế, nhưng chưa được xác nhận là Thần cốc.","theLucLienQuan":[],"nguon":["@c0416"]},{"id":"bien-gioi-phia-tay-thach-quoc","name":"Biên giới phía Tây Thạch quốc","cn":null,"capDo":"khac","parentId":"thach-quoc","blurb":"Khu vực biên giới phía tây của Thạch quốc, nơi đoàn Thạch Hạo đi qua trên đường trở về quê hương.","detail":"Đoàn người tới vùng vắng bóng người tại đây rồi mới dùng da Hư Không thú mở đường vượt Đại Hoang nhằm tránh để lộ hành tung.","theLucLienQuan":[],"nguon":["@c0432"]},{"id":"tam-vuc","name":"Tám vực Thiên, Địa, Huyền, Hoàng, Vũ, Trụ, Hồng, Hoang","cn":null,"capDo":"gioi-dien","parentId":null,"blurb":"Tám vực hợp thành phạm vi thế giới hiện tại, đối lập với những thế giới khác được nhắc đến trong lời bàn về trận pháp Thái cổ.","detail":"Nhị Ngốc Tử tuyên bố rằng trong tám vực Thiên, Địa, Huyền, Hoàng, Vũ, Trụ, Hồng, Hoang, không ai hiểu trận pháp Thái cổ trên Thiên Thần sơn hơn mình; ngoại lệ có thể là người đến từ thế giới khác. Trận pháp này được cho là có liên quan đến con đường đưa người rời khỏi tám vực.","theLucLienQuan":[],"nguon":["@c0433","@c0480"]},{"id":"tinh-tho-thien-nhan-toc","name":"Tịnh thổ Thiên Nhân tộc","cn":null,"capDo":"khac","parentId":"thien-than-son","blurb":"Tịnh thổ của Thiên Nhân tộc có linh khí dồi dào, hào quang rực rỡ, nhiều dị thú quý hiếm và thảo dược.","detail":"Vân Hi dẫn đoàn người vào khu vực này trên đường tới ngọn Thần sơn trọng yếu. Trong tịnh thổ còn có Bát Trân Kê, khiến Thạch Hạo muốn bắt về Thạch thôn nuôi dưỡng.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0434"]},{"id":"than-son-trong-yeu-thien-nhan-toc","name":"Thần sơn trọng yếu của Thiên Nhân tộc","cn":null,"capDo":"khac","parentId":"tinh-tho-thien-nhan-toc","blurb":"Ngọn Thần sơn hùng vĩ và rực rỡ, được xem là tòa Thần sơn quan trọng nhất của Thiên Nhân tộc.","detail":"Ngọn núi nằm trong tịnh thổ và được một tòa trận pháp che giấu, khiến người ngoài bình thường không thể nhìn thấy. Vân Hi mở trận pháp để ngọn núi hiện ra trước đoàn người.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0434"]},{"id":"con-duong-da-thai-co-thien-than-son","name":"Con đường đá Thái cổ","cn":null,"capDo":"khac","parentId":"thien-than-son","blurb":"Con đường đá cổ dẫn lên đỉnh Thiên Thần sơn, tương truyền do một vị Thiên Thần tự tay tạo ra.","detail":"Con đường phủ rêu xanh, ven đường có linh dược và thụy cầm xuất hiện.","theLucLienQuan":["Thiên Thần sơn"],"nguon":["@c0435"]},{"id":"duoc-dien-thien-than-son","name":"Dược điền Thiên Thần sơn","cn":null,"capDo":"khac","parentId":"thien-than-son","blurb":"Khu vực trồng nhiều linh dược của Thiên Thần sơn.","detail":"Dược điền được trận pháp duy trì tinh khí dồi dào, đồng thời có linh tuyền tẩm bổ đất và số lượng lớn linh dược cùng sinh trưởng.","theLucLienQuan":["Thiên Thần sơn"],"nguon":["@c0435"]},{"id":"tieu-the-gioi-cat-giu-thanh-duoc","name":"Tiểu thế giới cất giữ Thánh dược","cn":null,"capDo":"gioi-nho","parentId":"thien-than-son","blurb":"Tiểu thế giới bí mật cất giữ Thánh dược của Thiên Thần sơn, được ngăn cách với bên ngoài bằng trận pháp.","detail":"Không gian này có linh khí nồng đậm đến mức hóa thành chất lỏng, cùng linh tuyền, hoa cỏ, kỳ thạch và mùi thơm tác động tới hồn phách. Dẫn Hồn Liên sinh trưởng trong một hồ linh khí nằm sâu bên trong.","theLucLienQuan":["Thiên Thần sơn"],"nguon":["@c0435"]},{"id":"ho-linh-khi-trong-tieu-the-gioi","name":"Hồ linh khí trong tiểu thế giới","cn":null,"capDo":"khac","parentId":"tieu-the-gioi-cat-giu-thanh-duoc","blurb":"Hồ nước do linh khí hóa thành chất lỏng ngưng tụ trong tiểu thế giới cất giữ Thánh dược.","detail":"Dưới đáy hồ có phù văn và thiên địa thần thạch mang khí tức tương đồng với Dẫn Hồn Liên. Đây là nơi cây Thánh dược cắm rễ và cộng sinh lâu năm với những thần thạch xung quanh.","theLucLienQuan":["Thiên Thần sơn"],"nguon":["@c0435"]},{"id":"bai-da-sau-thien-than-son","name":"Bãi đá sau Thiên Thần Sơn","cn":"","capDo":"khac","parentId":"thien-than-son","blurb":"Bãi đá phía sau Thiên Thần Sơn, nơi ẩn giấu một cổ trận có khả năng mở đường vượt giới.","detail":"Cổ trận tại đây đã bị năm tháng bào mòn và hư hại nghiêm trọng. Trận đồ của Nhị Ngốc Tử có thể bổ khuyết những phần còn thiếu, nhưng việc tu bổ cần hơn chục loại thần liệu quý hiếm trước khi có thể dùng làm con đường rời khỏi Hoang Vực.","theLucLienQuan":["Thiên Thần Sơn"],"nguon":["@c0436"]},{"id":"bai-ky-thach","name":"Bãi kỳ thạch","cn":null,"capDo":"khac","parentId":"thien-than-son","blurb":"Khu đá rộng lớn có nhiều kỳ thạch hình thù khác lạ, che giấu một trận pháp vượt giới.","detail":"Vị trí của trận pháp giữa bãi đá rất khó nhận ra nếu không có ghi chép trên cốt thư. Thiên Nhân tộc dự định liên kết với các bộ tộc khác để thu gom lượng lớn nguyên liệu tu bổ trận pháp này.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0437"]},{"id":"thien-nhan-cac","name":"Thiên Nhân các","cn":null,"capDo":"khac","parentId":"thien-than-son","blurb":"Khu vực tại Thiên Thần sơn mà nhóm Thạch Hạo được cho phép tiến vào.","detail":"Việc nhóm Thạch Hạo tiến vào Thiên Nhân các bị người của Kim Sí Đại Bằng tộc dùng làm lý do để tới chất vấn thân phận và gây sức ép.","theLucLienQuan":["Thiên Nhân tộc","Kim Sí Đại Bằng tộc"],"nguon":["@c0437"]},{"id":"cung-dien-tren-dinh-nui-thien-than-son","name":"Cung điện trên đỉnh núi","cn":null,"capDo":"khac","parentId":"thien-than-son","blurb":"Thần điện nằm trên một ngọn núi hùng vĩ, được Thiên Nhân tộc bố trí làm nơi nghỉ ngơi cho nhóm Thạch Hạo.","detail":"Cung điện do Thần Linh xây dựng và mang khí tức thần thánh. Nơi đây từng dùng để tiếp đãi khách quý Hống tộc cùng những người được xem là ứng viên cô gia.","theLucLienQuan":["Thiên Nhân tộc","Hống tộc"],"nguon":["@c0437"]},{"id":"thuong-gioi","name":"Thượng giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Điểm đến mà Thiên Nhân tộc và Kim Sí Đại Bằng tộc dự định đăng lâm sau khi rời hạ giới.","detail":"Thượng giới được cho là nơi tồn tại các đạo thống cùng truyền thừa hoàn chỉnh của tổ tiên Thiên Nhân tộc và Kim Sí Đại Bằng tộc. Hai tộc dự định liên thủ, hỗ trợ lẫn nhau tại đây trước khi tìm được tông môn của mình, do hành trình tìm kiếm được nhận định là nguy hiểm và khó khăn.","theLucLienQuan":["Thiên Nhân tộc","Kim Sí Đại Bằng tộc"],"nguon":["@c0438"]},{"id":"than-son-bang-toc","name":"Thần sơn Bằng tộc","cn":null,"capDo":"khac","parentId":null,"blurb":"Thần sơn của Bằng tộc, nơi cất giữ Chân vũ Kim Bằng cực kỳ quý hiếm.","detail":"Bảo khố tại đây niêm phong số Chân vũ Kim Bằng còn lại của Bằng tộc. Kim Loạn Thiên sai người trở về nơi này lấy một chiếc giao cho Thạch Hạo.","theLucLienQuan":["Bằng tộc"],"nguon":["@c0441"]},{"id":"bay-than-son","name":"Bảy Thần sơn","cn":null,"capDo":"khac","parentId":null,"blurb":"Khu vực có trận pháp Thái cổ được các tộc chuẩn bị để vượt giới.","detail":"Các cường giả và hậu duệ Thần sơn dự định dùng trận pháp tại đây tiến vào Thượng giới tránh đại kiếp. Liễu Thần trực tiếp mở thông đạo hư không nên không cần mượn trận pháp của Bảy Thần sơn.","theLucLienQuan":[],"nguon":["@c0441"]},{"id":"than-tang-chi-ton","name":"Thần tàng Chí Tôn","cn":"","capDo":"khac","parentId":"dai-hoang","blurb":"Bảo tàng được cho là xây trên lưng một con rùa khổng lồ và có thể di chuyển dưới lòng đất.","detail":"Thần tàng Chí Tôn hiện diện tại Đại Hoang nhưng không cố định một chỗ vì vật mang nó có thể xuyên hành dưới lòng đất. Liễu Thần cảnh báo cảnh tượng lần này có thể là giả tượng hoặc một phần của bố cục nhằm dẫn dụ chí cường giả Thượng giới.","theLucLienQuan":[],"nguon":["@c0442","@c0478"]},{"id":"phia-nam-hoang-vuc","name":"Phía Nam Hoang Vực","cn":"","capDo":"khac","parentId":"hoang-vuc","blurb":"Khu vực phía Nam của Hoang Vực, nơi nhiều sinh linh nhìn thấy Pháp tướng khổng lồ của một giả Thần trong đại kiếp.","detail":"Khi giả Thần phát ánh đỏ dựng Pháp tướng chống lại lưỡi đao quy tắc, nhiều sinh linh tại phía Nam Hoang Vực nhận ra hình dáng ấy và liên tưởng tới một tượng thần trong ngôi miếu cổ ở phương Nam.","theLucLienQuan":[],"nguon":["@c0445"]},{"id":"yen-vu-lau","name":"Yên Vũ lâu","cn":"","capDo":"khac","parentId":"hoang-do-thach-quoc","blurb":"Một cổ lâu nổi tiếng nằm bên linh tuyền, quanh năm được bao phủ bởi hơi nước và những cơn mưa tự sinh.","detail":"Thạch Hạo và Nguyệt Thiền tới đây để kín đáo bàn luận về đại kiếp cùng bí mật của tám vực. Trong một gian phòng, Nguyệt Thiền dùng hào quang ngăn cách hai người với ngoại giới.","theLucLienQuan":[],"nguon":["@c0447"]},{"id":"nui-tim-ben-ngoai-bo-thien-giao","name":"Núi tím bên ngoài Bổ Thiên giáo","cn":"","capDo":"khac","parentId":null,"blurb":"Ngọn núi tím được linh khí bồi dưỡng qua vô tận năm tháng, sau đó thông linh thành thần.","detail":"Núi nằm bên ngoài Bổ Thiên giáo, từng dùng nhau thai của mình tế luyện thành Đạo thư. Sau khi thành thần, núi rời đi hàng trăm nghìn dặm để khai lập môn phái; những người thuộc truyền thừa này vẫn tôn kính và bảo vệ sơn môn Bổ Thiên giáo.","theLucLienQuan":["Bổ Thiên giáo","Môn phái của núi thần tím"],"nguon":["@c0449"]},{"id":"cam-dia-hoang-gia-thach-quoc","name":"Cấm địa hoàng gia Thạch Quốc","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Khu vực cấm thuộc hoàng cung Thạch Quốc, người thường không được phép đặt chân vào.","detail":"Tần Dũng cùng lực lượng vực ngoại đã xâm nhập khu vực này trong lúc can dự vào cục diện kế vị của Thạch Quốc.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0450"]},{"id":"thien-cung-hoang-kim","name":"Thiên cung hoàng kim","cn":"","capDo":"khac","parentId":"trung-uong-thien-cung","blurb":"Cung điện màu vàng ở trung tâm Thiên cung, nơi phát ra lời kêu gọi cộng hưởng với Thạch Hạo.","detail":"Thạch Hạo tiến vào cung điện sau khi cảm nhận sự cộng hưởng với vật Thạch Hoàng để lại. Trước khi bước vào, hắn quay lại quan sát Nguyệt Thiền tiên tử cùng hai thanh niên của Tây Phương giáo và Bất Lão sơn đang tiến tới.","theLucLienQuan":["Bổ Thiên giáo","Tây Phương giáo","Bất Lão sơn"],"nguon":["@c0452"]},{"id":"trung-uong-thien-cung","name":"Trung Ương Thiên Cung","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Thánh địa tinh thần và trung tâm hội tụ quốc vận của Thạch quốc.","detail":"Thiên cung được xây bằng đá hoàng kim, có mười hai trụ đá khắc Côn Bằng và Chân Long. Nội điện rộng lớn như một tiểu thế giới, lưu giữ long khí của các đời tổ tiên Thạch tộc và được nhiều tầng trận pháp bảo vệ; nơi sâu nhất đặt bảo tọa Nhân Hoàng cùng ngọc tỷ đã vỡ nát sau đại kiếp.","theLucLienQuan":["Thạch quốc","Thạch tộc"],"nguon":["@c0453"]},{"id":"tieu-the-gioi-cua-thach-hoang","name":"Tiểu thế giới của Thạch Hoàng","cn":"","capDo":"gioi-nho","parentId":"trung-uong-thien-cung","blurb":"Tiểu thế giới bí mật rộng mấy chục dặm nằm sau một cánh cửa trong hoàng cung Thạch quốc, là nơi cất giữ Nhân Hoàng ấn chân chính.","detail":"Không gian này tối tăm, mặt đất và hư không đều rạn nứt, có dấu hiệu gần như tan rã. Thạch Hạo tiến vào đây thăm dò và tìm thấy Nhân Hoàng ấn mang số mệnh của Thạch quốc.","theLucLienQuan":["Thạch quốc"],"nguon":["@c0454"]},{"id":"trung-uong-hoang-cung-thach-quoc","name":"Trung ương hoàng cung Thạch Quốc","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Khu vực trung tâm của hoàng cung Thạch Quốc, nơi Thạch Hạo độc chiến ba đại nhân kiệt.","detail":"Trận văn tại đây cộng hưởng với tân Nhân Hoàng, cản trở ba giáo bố trí sát trận. Túc vương cùng các Vương hầu am hiểu hoàng cung dự định phá bớt trận văn để biến khu vực này thành đất bình thường.","theLucLienQuan":["Thạch Quốc","Bổ Thiên giáo","Tây Phương giáo","Bất Lão sơn"],"nguon":["@c0457"]},{"id":"ngoc-hoa-mon","name":"Ngọc Hoa môn","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Một cửa ngõ trong hoàng cung Thạch Quốc, được xem là đường tắt và đường sống để rời khỏi nơi này.","detail":"Túc vương chỉ ra Ngọc Hoa môn là lối thoát của Thạch Hạo và yêu cầu lực lượng ba giáo phong tỏa nơi đây.","theLucLienQuan":["Thạch Quốc","Bổ Thiên giáo","Tây Phương giáo","Bất Lão sơn"],"nguon":["@c0457"]},{"id":"tuong-thanh-thach-do","name":"Tường thành Thạch đô","cn":"","capDo":"khac","parentId":"hoang-do-thach-quoc","blurb":"Tường thành màu đen bao quanh Thạch đô, được bảo vệ bởi màn sáng phù văn hộ thành.","detail":"Nguyệt Thiền dùng lực cắt thủng màn sáng để rời khỏi thành, còn Thạch Hạo triển khai pháp môn Côn Bằng xuyên qua màn sáng và tiếp tục truy sát nàng.","theLucLienQuan":["Hoàng triều Thạch Quốc","Bổ Thiên giáo"],"nguon":["@c0459"]},{"id":"linh-ho-ngoai-thach-do","name":"Linh hồ ngoài Thạch đô","cn":"","capDo":"khac","parentId":"hoang-do-thach-quoc","blurb":"Hồ nước lớn và trong vắt nằm ngoài Thạch đô, có linh khí dồi dào, cổ thụ và Thụy thú sinh sống quanh hồ.","detail":"Nguyệt Thiền dừng lại giao chiến với Thạch Hạo tại đây và kích hoạt Lục Thần trận đã bố trí từ trước. Trận pháp huy động lực lượng của hồ nước cùng núi sông xung quanh, dùng lôi điện và thần quang vây giết mục tiêu.","theLucLienQuan":["Bổ Thiên giáo"],"nguon":["@c0459"]},{"id":"tieu-the-gioi-trong-hop-quy","name":"Tiểu thế giới trong Hộp quý","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian ẩn bên trong hộp quý của thiên thần Thái Cổ, có thể che chở người ở bên trong khỏi sức sát thương của Lục Thần trận.","detail":"Tiểu thế giới này nằm trong Thế giới Hộp quý và được nối với bên ngoài bằng một thông đạo màu vàng. Thạch Hạo từng ẩn vào đây để tránh lôi điện của Lục Thần trận; sau khi bắt và phong ấn Nguyệt Thiền tiên tử, hắn cũng giam nàng trong không gian này.","theLucLienQuan":[],"nguon":["@c0460"]},{"id":"vung-dat-chay-den","name":"Vùng đất cháy đen","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường nơi Nguyệt Thiền bố trí sát trận và giao chiến với Thạch Hạo.","detail":"Nguyệt Thiền để lại tại đây một sát trận đủ uy hiếp cường giả. Sau trận chiến, Thạch Hạo dự định lợi dụng khu vực này để bố trí cạm bẫy, dẫn dụ những cường giả Bổ Thiên giáo đến tìm nàng.","theLucLienQuan":["Bổ Thiên giáo"],"nguon":["@c0461"]},{"id":"bao-kho-hoang-cung-thach-quoc","name":"Bảo khố hoàng cung Thạch quốc","cn":"","capDo":"khac","parentId":"hoang-do-thach-quoc","blurb":"Kho tàng trong hoàng cung Thạch quốc, bị phá hủy một góc nhưng phần còn lại đã được niêm phong.","detail":"Thạch Hạo tiến vào bảo khố để tìm thần trận, bảo thuật, pháp khí và những vật liệu cần cho việc dựng sát trận. Nơi này cũng được dùng làm bình phong che giấu việc nó bí mật rời Thạch đô.","theLucLienQuan":["Thạch quốc"],"nguon":["@c0461"]},{"id":"vung-dat-tai-uong","name":"Vùng đất tai ương","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực cách Thạch đô mấy ngàn dặm, được Thạch Hạo chọn làm nơi dựng cạm bẫy.","detail":"Thạch Hạo bí mật quay lại đây để bố trí trận pháp nhằm vào các Tôn giả Bổ Thiên giáo. Sau nửa ngày, nó xóa những dấu vết không cần thiết và cố ý giữ lại một số manh mối dẫn người điều tra tới hiện trường đã sắp đặt.","theLucLienQuan":["Bổ Thiên giáo"],"nguon":["@c0461"]},{"id":"thach-do","name":"Thạch đô","cn":"","capDo":"thanh","parentId":"thach-quoc-dia-danh-c0192","blurb":"Kinh đô của Thạch Quốc, được giới nghiêm sau khi Thạch Hạo lên ngôi và quét ngang tu sĩ ba giáo.","detail":"Khi dân chúng toàn thành đồng thanh tung hô tân Nhân Hoàng, tiếng hô hội tụ thành long khí Hoàng đạo bao phủ kinh thành.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0462"]},{"id":"ngu-hoa-vien-thach-quoc","name":"Ngự Hoa viên","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Vườn thuốc rộng lớn trong hoàng cung Thạch Quốc, có thổ nhưỡng đặc biệt và được linh tuyền tưới mỗi ngày.","detail":"Nơi đây từng trồng nhiều linh dược lâu năm, nhưng tu sĩ ba giáo cùng một số Vương hầu, hoàng tử và công chúa đã lợi dụng thời loạn để cướp bóc, khiến dược điền chỉ còn cây cối thưa thớt.","theLucLienQuan":["Thạch Quốc","Ba giáo vực ngoại"],"nguon":["@c0462"]},{"id":"ngoai-kho-hoang-gia-thach-quoc","name":"Ngoại khố hoàng gia","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Bảo khố bên ngoài của hoàng cung Thạch Quốc, hiện gần như trống rỗng sau đại kiếp và cuộc cướp bóc.","detail":"Một phần vật liệu trong kho đã được Thạch Hoàng lấy đi để luyện hóa trận pháp chống thiên phạt. Phần lớn số còn lại bị tu sĩ ba giáo cùng các hoàng tử và những phe tham gia tranh ngôi cướp sạch.","theLucLienQuan":["Thạch Quốc","Ba giáo vực ngoại"],"nguon":["@c0462"]},{"id":"noi-kho-hoang-gia-thach-quoc","name":"Nội khố hoàng gia","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Kho bí mật của hoàng gia Thạch Quốc, nằm sau một cửa đá chỉ có thể mở bằng Hoàng ấn.","detail":"Nội khố còn nguyên nhiều thần liệu, pháp khí và báu vật quý giá, trong đó có bốn pháp kiếm Thần Linh và chiến kích được đại năng Thượng cổ chế tạo phỏng theo kích Thiên Hoang của Côn Bằng.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0462"]},{"id":"dien-mieu","name":"Điển miếu","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Khu vực trọng yếu của hoàng tộc Thạch quốc, hợp thành từ Kinh Văn lâu và Bảo Thuật điện.","detail":"Điển miếu tồn tại từ thời thượng cổ, là nơi lưu giữ bí điển quốc gia và được xem là căn cơ của Thạch quốc. Khí tức đại đạo của các đời Nhân Hoàng tích tụ tại đây, còn bên trong có tĩnh thất dành riêng cho hoàng đế nghiên cứu điển tịch.","theLucLienQuan":["Thạch quốc","Hoàng tộc Thạch quốc"],"nguon":["@c0463"]},{"id":"tinh-that-nhan-hoang","name":"Tĩnh thất Nhân Hoàng","cn":"","capDo":"khac","parentId":"dien-mieu","blurb":"Gian phòng trong Điển miếu dành riêng cho Nhân Hoàng xem và nghiên cứu điển tịch.","detail":"Trong tĩnh thất, Hoàng ấn làm phòng đá rung chuyển và kích hoạt dấu ấn bảo thuật Toan Nghê ẩn trên vách, hiện ra giữa khói tím cùng sấm chớp vàng.","theLucLienQuan":["Thạch quốc","Hoàng tộc Thạch quốc"],"nguon":["@c0463"]},{"id":"chu-tuoc-doanh","name":"Chu Tước doanh","cn":"","capDo":"khac","parentId":"thach-do","blurb":"Quân doanh tinh nhuệ tại Thạch Đô, nơi phe phản loạn dựa vào viện trợ của Bất Lão sơn để chống lại tân hoàng.","detail":"Chỉ huy Chu Tước doanh ra lệnh bày trận chống quân triều đình, dựa vào các cao thủ, Thánh khí và sự chuẩn bị của Bất Lão sơn. Đại trận bị Thạch Hạo, Chiến Vương và thị vệ lớn tuổi phá tan; chỉ huy phản loạn bị chém đầu, còn những binh sĩ không trực tiếp tham dự âm mưu được miễn tội.","theLucLienQuan":["Chu Tước doanh","Bất Lão sơn","Thạch quốc"],"nguon":["@c0465"]},{"id":"than-mieu-vu-than","name":"Thần miếu Vũ Thần","cn":"","capDo":"khac","parentId":"vu-vuong-phu-dia-diem","blurb":"Thần miếu nằm trong Vũ Vương phủ, là nơi thờ phụng Vũ Thần và chỗ tộc nhân Vũ tộc tìm đến lánh nạn.","detail":"Nơi đây cất giữ pháp chỉ và tượng đá Vũ Thần. Trong trận chiến cuối cùng của Vũ Vương, thần kích trấn quốc xuyên thủng tượng đá, kéo nó vào miếu và đánh trúng Vũ Vương; sau đó tượng đá hóa thành bột mịn còn toàn bộ thần miếu sụp đổ thành phế tích.","theLucLienQuan":["Vũ Vương Phủ","Vũ tộc"],"nguon":["@c0466"]},{"id":"cung-dien-chua-chien-loi-pham","name":"Cung điện chứa chiến lợi phẩm","cn":"","capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Nơi tập trung bảo khố và vật liệu tịch thu từ phủ đệ của các Vương hầu bị tiêu diệt.","detail":"Thạch Hạo kiểm tra chiến lợi phẩm tại đây và tìm thấy một khối đá u tối chứa vật chất linh tính có thể dung hợp với Bất Diệt Kim Thân.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0467"]},{"id":"kiep-tho-noi-nguyet-thien-mat-tich","name":"Kiếp thổ nơi Nguyệt Thiền mất tích","cn":null,"capDo":"khac","parentId":null,"blurb":"Vùng kiếp thổ nơi Nguyệt Thiền xuất hiện lần cuối, đồng thời là địa điểm Thạch Hạo bố trí sát cục.","detail":"Khu vực này vốn có hồ lớn nhưng đã khô cạn, mặt đất nứt vỡ và núi non sụp đổ. Nơi đây còn tàn trận Lôi bộ của Lục Thần trận và trở thành hiện trường sát trận tiêu diệt đạo cô cùng các đệ tử Bổ Thiên giáo.","theLucLienQuan":["Bổ Thiên giáo"],"nguon":["@c0470"]},{"id":"day-nui-ngoai-thach-do","name":"Dãy núi ngoài Thạch đô","cn":null,"capDo":"khac","parentId":"thach-quoc","blurb":"Dãy núi bên ngoài Thạch đô, nơi nhiều cao thủ của ba giáo ẩn nấp.","detail":"Đạo cô trung niên trở về điểm dừng chân của Bổ Thiên giáo tại khu vực này sau khi bị Thạch Hạo truy sát. Nhiều cường giả của ba giáo cũng ẩn mình trong dãy núi ngoài thành.","theLucLienQuan":["Bổ Thiên giáo","Ba giáo"],"nguon":["@c0470"]},{"id":"to-te-dan","name":"Tổ tế đàn","cn":null,"capDo":"khac","parentId":"hoang-cung-thach-quoc","blurb":"Tế đàn trong hoàng cung được dùng để quan sát cảnh vật ở xa và mở thông đạo hư không tới kiếp thổ.","detail":"Thạch Hạo kích hoạt tổ tế đàn để Chiến vương và Bằng Cửu theo dõi sát cục tại kiếp thổ. Sau đó, nhóm người mượn sức nơi này mở thông đạo hư không và hoàn thiện một trận pháp chuyên đối phó Tôn giả.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0470"]},{"id":"phe-tich-ngoai-hoang-do-thach-quoc","name":"Phế tích ngoài hoàng đô Thạch Quốc","cn":null,"capDo":"khac","parentId":"thach-quoc-dia-danh-c0192","blurb":"Phế tích nằm bên ngoài hoàng đô Thạch Quốc, nơi từng xuất hiện một móng vuốt khổng lồ.","detail":"Một móng vuốt lớn xuất hiện từ phế tích, vươn lên trời cao và đánh nát mây xanh. Tin tức này khiến Thạch Hạo liên hệ tới con rùa khổng lồ từng thấy ngoài Thạch thôn và nghi ngờ sát cục quanh thần tàng chí tôn đang dần hiện rõ.","theLucLienQuan":["Thạch Quốc"],"nguon":["@c0476"]},{"id":"vung-dat-cu-cung-dien-chi-ton","name":"Vùng đất cũ của Cung điện chí tôn","cn":null,"capDo":"khac","parentId":null,"blurb":"Di tích được cho là có quan hệ chặt chẽ với thần tàng chí tôn và Cung điện chí tôn.","detail":"Theo suy đoán của Ma nữ, vùng đất cũ này có thể cùng nguồn gốc với thần tàng chí tôn và có khả năng dịch chuyển giữa các vực. Nơi đây gắn với truyền thừa vô thượng nhưng cũng ẩn chứa nguy hiểm đủ uy hiếp cả Thần.","theLucLienQuan":["Cung điện chí tôn"],"nguon":["@c0476"]},{"id":"truc-vien-trong-hoang-cung","name":"Trúc viên trong hoàng cung","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực thanh tịnh trong hoàng cung, nơi Thạch Hạo nghỉ ngơi và tiếp chuyện Nguyệt Thiền cùng Ma nữ.","detail":"Trúc viên có rừng trúc, phòng trúc, bàn ghế đá và giường trúc. Thạch Hạo trò chuyện riêng với Nguyệt Thiền tại đây trước khi Ma nữ xuất hiện.","theLucLienQuan":[],"nguon":["@c0477"]},{"id":"phe-tich-hoang-do-hoa-quoc","name":"Phế tích hoàng đô Hỏa quốc","cn":"","capDo":"thanh","parentId":"hoa-quoc","blurb":"Hoàng đô Hỏa quốc đã hóa thành phế tích nhưng chưa biến mất hoàn toàn, trở thành tâm điểm tranh đoạt trong đại kiếp.","detail":"Các đại nhân vật từ Thượng giới, sinh linh dạng vệt sáng và rùa khổng lồ cùng hội tụ tại đây. Sát trận thứ ba phát ra kiếm khí và khí hỗn độn, sau đó đại kích Thiên Hoang cũng tiến vào khu vực này.","theLucLienQuan":["Hỏa quốc"],"nguon":["@c0478"]},{"id":"cung-dien-chi-ton","name":"Cung điện Chí Tôn","cn":"","capDo":"khac","parentId":"phe-tich-hoang-do-hoa-quoc","blurb":"Cung điện được cho là nơi cất giữ bản trung Siêu Thoát của Nguyên Thủy Chân Giải.","detail":"Nhiều cường giả khao khát tiến vào Cung điện Chí Tôn để tìm cơ duyên nhưng trước đó đều thất bại. Trong đại kiếp, các tồn tại cấm kỵ hạ giới và tiến vào phế tích để tranh đoạt mục tiêu liên quan đến nơi này.","theLucLienQuan":[],"nguon":["@c0478"]},{"id":"khe-nui-ngoai-duoc-do","name":"Khe núi ngoài Dược đô","cn":"","capDo":"khac","parentId":"hoang-vuc","blurb":"Chiến trường đặt linh căn đệ nhất và sát trận thứ năm, nơi nhiều bá chủ cùng chí bảo tiến hành cuộc tranh đoạt.","detail":"Các trận pháp từng che phủ khu vực này bị phá, khiến địa hình rộng hàng trăm nghìn dặm hiện ra. Máu thịt, thần lực và tinh khí của những tồn tại bị sát trận giết chết đều bị vùng đất hút về trung tâm linh căn.","theLucLienQuan":[],"nguon":["@c0479"]},{"id":"lao-tu-hien-tai","name":"Lao tù hiện tại","cn":"","capDo":"khac","parentId":null,"blurb":"Địa vực bị bà lão mang sọt thuốc xem là một lao tù dùng để thu hái dược liệu.","detail":"Bà lão nhận định nơi này đã bị hái sạch rồi phá giới rời đi, cho thấy các cường giả đủ tư cách làm dược liệu tại đây có thể đã bị thu bắt gần hết.","theLucLienQuan":[],"nguon":["@c0479"]},{"id":"bay-lao-tu-con-lai","name":"Bảy lao tù còn lại","cn":"","capDo":"khac","parentId":null,"blurb":"Bảy địa vực khác mà bà lão mang sọt thuốc dự định tìm đến sau khi rời lao tù hiện tại.","detail":"Các địa vực này nằm ngoài lao tù vừa bị thu hái sạch và là mục tiêu tiếp theo trong cuộc săn những sinh linh được bà lão xem như đại dược nhân gian.","theLucLienQuan":[],"nguon":["@c0479"]},{"id":"huyen-vuc","name":"Huyền vực","cn":null,"capDo":"vuc","parentId":"tam-vuc","blurb":"Một trong tám vực của Hạ giới, nơi Bất Lão sơn tọa lạc.","detail":"Bà lão mang sọt thuốc tiến vào Huyền vực, xâm nhập Bất Lão sơn và bắt đi nhiều nhân vật cấp lão tổ đang bế quan.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0480"]},{"id":"tay-phuong-giao-tinh-tho","name":"Tây Phương giáo tịnh thổ","cn":null,"capDo":"khac","parentId":null,"blurb":"Tịnh thổ của Tây Phương giáo gồm nhiều linh sơn và được các tầng trận pháp thần linh bảo vệ.","detail":"Nơi đây có phật quang, sông vàng, cổ dược, thần thú, vườn thuốc và thần trì chứa sen thần. Đạo nhân sáu tay xâm nhập, bắt các đại Tôn giả và thu lấy nhiều tài nguyên trước khi cùng Trượng Lục Kim Thân chuyển chiến trường ra vực ngoại.","theLucLienQuan":["Tây Phương giáo"],"nguon":["@c0480"]},{"id":"dao-dai-bien-gioi-huyen-vuc","name":"Đạo đài biên giới Huyền vực","cn":"","capDo":"khac","parentId":"huyen-vuc","blurb":"Đạo đài ở biên giới Huyền vực, dùng để tiếp nhận những người từ vực ngoại trở về.","detail":"Nơi này do nhiều giáo cùng quản lý. Khi Thạch Hạo và Tần Minh tới đây, thân phận của Thạch Hạo bị nhận ra; sau đó đạo đài náo động vì có người từ Thượng giới giáng xuống Huyền vực.","theLucLienQuan":["Bất Lão sơn","Các giáo ở tám vực"],"nguon":["@c0482"]},{"id":"tinh-khong-ha-gioi","name":"Tinh không hạ giới","cn":"","capDo":"khac","parentId":"tam-vuc","blurb":"Tinh không quan sát được từ hạ giới chỉ có một số ít ngôi sao là thật.","detail":"Nhiều ngôi sao tại đây do các chí tôn cổ đại dùng pháp lực cô đọng, phần còn lại là hình chiếu của ngân hà thượng giới.","theLucLienQuan":[],"nguon":["@c0484"]},{"id":"thien-mon","name":"Thiên môn","cn":"","capDo":"khac","parentId":null,"blurb":"Cửa ngõ để sinh linh hạ giới tiến vào thượng giới, được kiểm soát bằng việc thẩm tra căn nguyên nghiêm ngặt.","detail":"Người thuộc các đạo thống thượng giới lưu lại tại hạ giới có thể thuận lợi hơn khi đi qua. Tán tu và những người không có lai lịch phù hợp phải chịu hạn chế lớn vì tám vực từng giam giữ nhiều đại hung.","theLucLienQuan":[],"nguon":["@c0484"]},{"id":"thanh-nhai-bat-lao-son","name":"Thánh nhai Bất Lão sơn","cn":null,"capDo":"khac","parentId":"bat-lao-son","blurb":"Khu vực ngoài Bất Lão sơn, là điểm dừng của những thuyền lớn đưa khách tới.","detail":"Sườn dốc cao được bao phủ bởi thải quang và tiên khí, có ký hiệu hiện lên như sao trời. Vách đá đã được tế luyện thành bảo cụ kiên cố, bất diệt và nằm cách khu vực sơn môn thật sự một quãng đường.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0485"]},{"id":"ngu-hanh-son","name":"Ngũ Hành sơn","cn":null,"capDo":"khac","parentId":"bat-lao-son","blurb":"Ngọn núi phụ hình bàn tay nằm tại Bất Lão sơn, mang khí tượng bất diệt và có vai trò bảo vệ thánh địa.","detail":"Dân gian truyền rằng bên dưới Ngũ Hành sơn phong ấn một nhân vật cái thế đã trải qua năm tháng dài lâu mà vẫn khó bị luyện chết, song Bất Lão sơn luôn phủ nhận lời đồn này.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0485","@c0494"]},{"id":"ha-gioi","name":"Hạ giới","cn":null,"capDo":"gioi-dien","parentId":null,"blurb":"Giới vực có thiên địa khiếm khuyết và pháp tắc không đầy đủ, là nơi Thạch Hạo cùng nhiều sinh linh bản địa trưởng thành.","detail":"Điều kiện thiên địa tại đây gây bất lợi cho người sinh trưởng trong hạ giới, nhưng lại có giá trị tôi luyện đặc biệt đối với người từ thượng giới mang đạo thai hoàn mỹ như Nguyệt Thiền.","theLucLienQuan":[],"nguon":["@c0485"]},{"id":"than-vuong-dien","name":"Thần Vương điện","cn":null,"capDo":"khac","parentId":"bat-lao-son","blurb":"Đại điện hùng vĩ nằm sâu trong Bất Lão sơn, gần một dòng tử tuyền.","detail":"Điện được dựng để thờ và tế bái các cường giả có công lao và cảnh giới tương ứng, kể cả những người đang tu hành tại Thượng giới. Thạch Hạo từng bị giữ chờ trong thiên điện của nơi này.","theLucLienQuan":["Bất Lão sơn","Tần tộc"],"nguon":["@c0486"]},{"id":"thien-than-dien","name":"Thiên Thần điện","cn":null,"capDo":"khac","parentId":"bat-lao-son","blurb":"Một trong những cung điện hùng vĩ nằm sâu trong Bất Lão sơn.","detail":"Thiên Thần điện hiện diện giữa quần thể cung điện san sát được dựng cho các cường giả của Bất Lão sơn, cho thấy nơi đây từng xuất hiện nhiều nhân vật có cảnh giới cao thâm.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0486"]},{"id":"khe-nui-ngu-hanh","name":"Khe núi Ngũ Hành","cn":null,"capDo":"khac","parentId":"ngu-hanh-son","blurb":"Vùng thần thổ nằm trong dãy núi Ngũ Hành, thường đóng kín vì là nơi lão tổ thần linh bế quan.","detail":"Bên trong khe núi có trời quang, linh đằng, thảo dược và cổ mộc. Cha mẹ Thạch Hạo tu luyện tại đây trong một đạo lô bất hủ; khi Thạch Hạo tới, khe núi được dự kiến còn hai ngày nữa mới mở.","theLucLienQuan":["Bất Lão sơn","Tần tộc"],"nguon":["@c0486"]},{"id":"tien-coc-trong-khe-nui","name":"Tiên cốc trong khe núi","cn":"","capDo":"khac","parentId":"khe-nui-ngu-hanh","blurb":"Không gian mênh mông ẩn sau hai vách núi, được hé lộ khi vách đá từ từ dạt sang hai bên.","detail":"Sau khi lối vào mở ra, Thạch Hạo nhấc Tần Trạm lên và tiến vào tiên cốc bên trong khe núi.","theLucLienQuan":[],"nguon":["@c0489"]},{"id":"coc-than","name":"Cốc thần","cn":null,"capDo":"gioi-nho","parentId":"bat-lao-son","blurb":"Sơn cốc thuộc Bất Lão sơn, có tinh khí và hào quang dồi dào, pháp tắc cùng trật tự đầy đủ khác thường.","detail":"Cốc thần là một vùng thần thổ có đại đạo viên mãn giữa thiên địa hạ giới vốn thiếu khuyết. Nơi đây chia thành nhiều khu vực, có linh cầm, dị thú, thác nước và khí tức thần linh; các truyền thừa niết bàn cùng những pháp môn khác được lưu lại trong sơn cốc.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0490"]},{"id":"tinh-tho-lao-to-bat-lao-son","name":"Tịnh thổ của lão tổ Bất Lão sơn","cn":null,"capDo":"khac","parentId":"coc-than","blurb":"Khu tịnh thổ nằm cuối đại lộ kim quang trong Cốc thần, là nơi lão tổ Bất Lão sơn hiện thân.","detail":"Nơi đây có linh tuyền, bảo dược và một cổ thụ tỏa ra đạo vận. Lão tổ Bất Lão sơn mặc chiến y hoàng kim, ngồi xếp bằng dưới cổ thụ và gặp Thạch Hạo tại đây.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0491"]},{"id":"tinh-tho-cha-me-thach-hao","name":"Tịnh thổ của cha mẹ Thạch Hạo","cn":null,"capDo":"khac","parentId":"coc-than","blurb":"Khu tịnh thổ trong Cốc thần nơi cha mẹ Thạch Hạo cư trú, bị trận pháp thần linh ngăn cách với bên ngoài.","detail":"Bên trong có kiến trúc giống một góc Võ Vương phủ cùng rừng trúc dùng làm nơi tu luyện. Cha mẹ Thạch Hạo cảm ứng được con trai đã tới rất gần nhưng chưa thể trực tiếp gặp nó vì sự ngăn cách của trận pháp.","theLucLienQuan":["Bất Lão sơn"],"nguon":["@c0491"]},{"id":"dai-dien-dong","name":"Đại điện đồng","cn":null,"capDo":"khac","parentId":"bat-lao-son","blurb":"Điện đồng hoen gỉ tọa lạc trên một ngọn núi của Bất Lão sơn.","detail":"Đây là nơi Tần Vũ ngồi tu hành, vận chuyển trận pháp và tế bái để dẫn sức mạnh từ Ngũ Hành sơn. Phía trước điện có một tế đàn bằng đồng dùng để duy trì hoặc ngăn cách liên hệ với thượng giới.","theLucLienQuan":["Bất Lão sơn","Tần tộc"],"nguon":["@c0492"]},{"id":"ho-niet-ban","name":"Hồ niết bàn","cn":null,"capDo":"khac","parentId":"bat-lao-son","blurb":"Trọng địa của Bất Lão sơn gồm năm hồ chứa chất lỏng óng ánh, có thể giúp người đủ kinh diễm lột xác và niết bàn trọng sinh.","detail":"Năm hồ nằm trong một tịnh thổ sâu bên trong trận pháp. Trước hồ có bia cổ khắc các cảnh giới Động thiên, Hóa linh, Minh văn và Liệt trận; Thạch Hạo được Tần Vũ truyền tống tới đây để tu hành và tìm cơ hội lột xác.","theLucLienQuan":["Bất Lão sơn","Tần tộc"],"nguon":["@c0492"]},{"id":"chien-truong-anh-linh","name":"Chiến trường anh linh","cn":"","capDo":"khac","parentId":"bat-lao-son","blurb":"Không gian đặc dị do Tần Vũ bố trí, nơi hàng vạn anh linh hợp thành linh vực để kéo thần hồn người bị nhốt rời khỏi thể xác.","detail":"Chiến trường chứa hàng vạn anh linh và các linh thể màu bạc, được dùng phối hợp với hồ niết bàn nhằm khắc lại bí mật cùng pháp môn của Thạch Hạo. Một khe hở bị cắt mở về sau cho phép người bên ngoài mơ hồ nhìn thấy hai thiếu niên đang giao chiến bên trong.","theLucLienQuan":["Bất Lão sơn","Tần tộc"],"nguon":["@c0493"]},{"id":"chien-truong-thuong-co-trong-tran-phap","name":"Chiến trường thượng cổ trong trận pháp","cn":"","capDo":"khac","parentId":"chien-truong-anh-linh","blurb":"Cảnh vực thượng cổ tràn ngập âm khí, cây cỏ biến mất và hàng vạn anh linh xuất hiện từ mặt đất, hư không cùng mây đen.","detail":"Đây là diện mạo chiến trường hiện ra trong không gian trận pháp do Tần Vũ sắp đặt. Năm hồ niết bàn là khu vực duy nhất tại đây cuồn cuộn dương khí và tỏa ra sóng nhiệt.","theLucLienQuan":["Bất Lão sơn","Tần tộc"],"nguon":["@c0493"]},{"id":"khong-gian-hoa-ma-tran","name":"Không gian Hóa ma trận","cn":"","capDo":"khac","parentId":"bat-lao-son","blurb":"Không gian tiếp nhận chiến ý và pháp lực bị Hóa ma trận rút khỏi Thạch Hạo.","detail":"Chiến ý và pháp lực được chuyển vào đây rồi hình thành một bản thể khác của Thạch Hạo để giao chiến với Tần Hạo, qua đó biến cuộc rèn luyện thành tình thế hai anh em bị ép đối đầu.","theLucLienQuan":["Bất Lão sơn","Tần tộc"],"nguon":["@c0493"]},{"id":"khu-vuc-tran-ap-duoi-ngu-hanh-son","name":"Khu vực trấn áp dưới Ngũ Hành sơn","cn":"","capDo":"khac","parentId":"ngu-hanh-son","blurb":"Nơi sinh linh bất diệt bị xích thần Ngũ hành giam giữ qua vô tận năm tháng.","detail":"Sau khi Ngũ Hành sơn bị xới tung, sinh linh bị trấn áp tại đây lần đầu thấy lại ánh mặt trời. Hắn thức tỉnh, đứng dậy giữa xích thần và hút tinh khí thiên địa để khôi phục nguyên khí.","theLucLienQuan":["Tần tộc"],"nguon":["@c0497"]},{"id":"son-coc-giam-giu-bat-lao-son","name":"Sơn cốc giam giữ tại Bất Lão Sơn","cn":"","capDo":"khac","parentId":"bat-lao-son","blurb":"Sơn cốc nơi vợ chồng Thạch Tử Lăng và Tần Di Ninh bị giam lỏng, được trận pháp thần linh phong tỏa.","detail":"Bên trong sơn cốc có hồ nước xanh, rừng trúc, kiến trúc cổ mang phong cách Võ Vương phủ và linh khí gần như hóa lỏng. Sâu trong trận pháp còn có phù văn ẩn cùng một tế đàn kỳ lạ tại khu vực trung tâm.","theLucLienQuan":["Bất Lão Sơn","Tần tộc thượng giới"],"nguon":["@c0499"]}]};
